# FAQ grouped into tabs on the page. Original FAQ order is: getting started (5), leads (11), pricing (5), delivery (5),
# compliance (6), quality (5), working together (6). FAQ_MORE items are slotted into the right group by question.
_more = {q: (q, a) for q, a in FAQ_MORE}
_m = lambda *qs: [_more[q] for q in qs]
FAQ_GROUPS = [
    ('Getting started', FAQ[0:1] + _m('Where can I buy business loan leads in the UK?') + FAQ[1:5] + _m('Can I see a sample lead?')),
    ('Leads and qualification', FAQ[5:16] + _m('Do you supply merchant cash advance (MCA) leads?', 'How is a lead different from a referral?', 'How do you decide which partner gets a lead?', 'What do business owners expect when you call?')),
    ('Pricing and volumes', FAQ[16:21] + _m('Do you guarantee a number of leads each month?')),
    ('Delivery and CRM', FAQ[21:26]),
    ('Compliance and consent', FAQ[26:32]),
    ('Lead quality', FAQ[32:37] + _m('What if a business has already found finance by the time I call?', 'Can I give feedback on individual leads?')),
    ('Working together', FAQ[37:42] + _m('Do you work with brokers across the whole of the UK?') + FAQ[42:43]),
]
FAQ = [qa for _, qas in FAQ_GROUPS for qa in qas]
assert len(FAQ) == 53 and len({q for q, _ in FAQ}) == 53
